"""Compare the outputs regenerated by the author's code in a sandbox with the committed outputs/ (read-only).

  python review/scripts/02_compare_sandbox.py <sandbox_outputs_dir> [<sandbox_outputs_dir2> ...]

For every file of the sandbox that was rewritten during the rerun (mtime after the copy), compare with outputs/<name>:
CSV / CSV.GZ - same shape, same non-numeric cells, max abs difference of numeric cells; JSON - recursive comparison of
numbers (tolerance 1e-6), keys with run time / timing are ignored.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parents[2]
REPO_OUT = ROOT / "outputs"
SKIP_KEYS = {"seconds", "time"}
rows = []


def cmp_json(a, b, path=""):
    diffs = []
    if isinstance(a, dict) and isinstance(b, dict):
        for k in sorted(set(a) | set(b)):
            if k in SKIP_KEYS or k.endswith("_s"):
                continue
            if k not in a or k not in b:
                diffs.append(f"{path}/{k}: missing on one side")
            else:
                diffs += cmp_json(a[k], b[k], f"{path}/{k}")
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            diffs.append(f"{path}: list length {len(a)} vs {len(b)}")
        else:
            for i, (x, y) in enumerate(zip(a, b)):
                diffs += cmp_json(x, y, f"{path}[{i}]")
    elif isinstance(a, (int, float)) and isinstance(b, (int, float)) and not isinstance(a, bool):
        if not (abs(a - b) <= 1e-6 or (np.isnan(a) and np.isnan(b))):
            diffs.append(f"{path}: {a} vs {b}")
    elif a != b:
        diffs.append(f"{path}: {str(a)[:60]!r} vs {str(b)[:60]!r}")
    return diffs


def cmp_csv(pa: Path, pb: Path):
    a, b = pd.read_csv(pa), pd.read_csv(pb)
    if a.shape != b.shape or list(a.columns) != list(b.columns):
        return f"shape {a.shape} vs {b.shape}", np.nan
    num = [c for c in a.columns if pd.api.types.is_numeric_dtype(a[c]) and pd.api.types.is_numeric_dtype(b[c])]
    oth = [c for c in a.columns if c not in num]
    bad = sum(int((a[c].fillna("§") .astype(str) != b[c].fillna("§").astype(str)).sum()) for c in oth)
    mx = 0.0
    for c in num:
        x, y = a[c].to_numpy(float), b[c].to_numpy(float)
        if (np.isnan(x) != np.isnan(y)).any():
            bad += int((np.isnan(x) != np.isnan(y)).sum())
        d = np.nanmax(np.abs(x - y)) if (~np.isnan(x) & ~np.isnan(y)).any() else 0.0
        mx = max(mx, float(d))
    return ("identical" if bad == 0 and mx <= 1e-6 else f"non-numeric/NaN mismatches {bad}"), mx


def main():
    for sb in sys.argv[1:]:
        sb = Path(sb)
        ref_time = min(p.stat().st_mtime for p in sb.iterdir() if p.is_file())  # copied files keep the source mtime
        for p in sorted(sb.iterdir()):
            if not p.is_file():
                continue
            ref = REPO_OUT / p.name
            if not ref.exists():
                rows.append((p.name, "NEW (not in outputs/)", ""))
                continue
            if abs(p.stat().st_mtime - ref.stat().st_mtime) < 1 and p.stat().st_size == ref.stat().st_size:
                continue  # untouched copy
            if p.suffix == ".json":
                d = cmp_json(json.loads(p.read_text(encoding="utf-8")), json.loads(ref.read_text(encoding="utf-8")))
                rows.append((p.name, "identical" if not d else f"{len(d)} diffs", "; ".join(d[:4])))
            elif p.name.endswith((".csv", ".csv.gz")):
                verdict, mx = cmp_csv(p, ref)
                rows.append((p.name, verdict, f"max |diff| {mx:.2e}"))
            else:
                same = p.read_bytes() == ref.read_bytes()
                rows.append((p.name, "identical bytes" if same else "bytes differ", ""))
    out = pd.DataFrame(rows, columns=["file", "verdict", "detail"])
    print(out.to_string(index=False))
    (ROOT / "review" / "results").mkdir(parents=True, exist_ok=True)
    out.to_csv(ROOT / "review" / "results" / "02_sandbox_vs_outputs.csv", index=False)


if __name__ == "__main__":
    main()
